// Checks on repository files that are not Rust code: CI workflows and site configuration.
// Each test names the finding of docs/security/BASELINE_FINDINGS.md it guards.

use std::path::{Path, PathBuf};

fn root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
}

fn read(rel: &str) -> String {
    std::fs::read_to_string(root().join(rel)).unwrap_or_else(|e| panic!("read {rel}: {e}"))
}

// Workflows written by hand. `release.yml` is generated by cargo-dist and is left as generated.
fn workflows() -> Vec<PathBuf> {
    let mut out = Vec::new();
    for dir in [".github/workflows", "registry-template/.github/workflows"] {
        for entry in std::fs::read_dir(root().join(dir)).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            if name.ends_with(".yml") && !(dir == ".github/workflows" && name == "release.yml") {
                out.push(path);
            }
        }
    }
    assert!(out.len() >= 5, "workflows not found: {out:?}");
    out
}

// B-S3: a tag or branch of an action can be moved to other code; a full commit hash cannot.
#[test]
fn actions_are_pinned_to_commit_hashes() {
    let mut bad = Vec::new();
    for path in workflows() {
        let text = std::fs::read_to_string(&path).unwrap();
        for (i, line) in text.lines().enumerate() {
            let Some(rest) = line
                .trim_start()
                .trim_start_matches("- ")
                .strip_prefix("uses: ")
            else {
                continue;
            };
            let spec = rest.split_whitespace().next().unwrap_or_default();
            let pinned = spec.rsplit_once('@').is_some_and(|(_, r)| {
                r.len() == 40
                    && r.bytes()
                        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
            });
            if !pinned && !spec.starts_with("./") {
                bad.push(format!("{}:{}: {spec}", path.display(), i + 1));
            }
        }
    }
    assert!(
        bad.is_empty(),
        "actions not pinned to a commit:\n{}",
        bad.join("\n")
    );
}

// B-S4: without a `permissions:` block a job gets the repository's default token scope, which
// can include write access.
#[test]
fn ci_token_is_read_only() {
    let text = read(".github/workflows/ci.yml");
    let block: Vec<&str> = text
        .lines()
        .skip_while(|l| *l != "permissions:")
        .skip(1)
        .take_while(|l| l.starts_with("  "))
        .collect();
    assert_eq!(
        block,
        ["  contents: read"],
        "top-level permissions of ci.yml"
    );
    assert!(
        !text
            .lines()
            .any(|l| l.trim_start().starts_with("permissions:") && l.starts_with(' ')),
        "a job in ci.yml widens the permissions"
    );
}

// B-S1: Cloudflare Pages sends the headers of `site/public/_headers` (copied into the build) with
// every page of qxide.dev.
#[test]
fn site_sends_security_headers() {
    let text = read("site/public/_headers");
    let mut lines = text
        .lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'));
    assert_eq!(lines.next(), Some("/*"), "headers must apply to every path");
    let headers: Vec<(String, String)> = lines
        .map(|l| {
            let (k, v) = l.trim().split_once(':').expect("`Name: value`");
            (k.to_ascii_lowercase(), v.trim().to_string())
        })
        .collect();
    let get = |name: &str| {
        headers
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_str())
            .unwrap_or_else(|| panic!("missing {name}"))
    };
    assert_eq!(get("x-content-type-options"), "nosniff");
    assert_eq!(get("x-frame-options"), "DENY");
    assert!(get("referrer-policy").starts_with("strict-origin"));
    let csp = get("content-security-policy");
    for part in [
        "frame-ancestors 'none'",
        "object-src 'none'",
        "base-uri 'self'",
    ] {
        assert!(csp.contains(part), "CSP lacks {part}: {csp}");
    }
}

// B-S7: the Vite dev server may read only the site and the examples it bundles, not the whole
// repository (target/, .git/, local files).
#[test]
fn dev_server_reads_only_the_site_and_examples() {
    let text = read("site/vite.config.ts");
    let start = text.find("allow: [").expect("server.fs.allow") + "allow: [".len();
    let list = &text[start..start + text[start..].find(']').unwrap()];
    let dirs: Vec<&str> = list
        .split(',')
        .map(|s| s.trim().trim_matches('\''))
        .filter(|s| !s.is_empty())
        .collect();
    assert_eq!(dirs, [".", "../examples/qx"], "server.fs.allow");
}
